css:
.app { grid-template-rows: var(--topbar-h) minmax(0, 1fr) var(--bottombar-h); height: 100dvh; display: grid; overflow: hidden; }
.topbar { border-bottom: 1px solid var(--line); background: var(--sheen), color-mix(in srgb, var(--sheet) 92%, transparent); z-index: 5; align-items: center; gap: 14px; padding: 0px 16px 0px 18px; display: flex; position: relative; box-shadow: rgba(0, 0, 0, 0.25) 0px 1px, rgba(0, 0, 0, 0.8) 0px 10px 30px -18px; }
.brand { color: var(--text); letter-spacing: -0.01em; align-items: center; gap: 8px; font-weight: 700; text-decoration: none; display: inline-flex; }
.brand__mark { width: 28px; height: 28px; color: var(--accent-contrast); background: linear-gradient(160deg, color-mix(in srgb, var(--accent) 75%, white), var(--accent) 60%, color-mix(in srgb, var(--accent) 80%, black)); box-shadow: inset 0 1px 0 #ffffff4d, 0 4px 14px -4px color-mix(in srgb, var(--accent) 75%, transparent); border-radius: 8px; place-items: center; display: grid; }
.brand__mark svg { width: 16px; height: 16px; }
.chapter-btn { border: 1px solid var(--line); background: var(--sheen), var(--surface); cursor: pointer; min-width: 0px; height: 36px; color: var(--text); box-shadow: var(--edge-hi), var(--elev-1); border-radius: 10px; align-items: center; gap: 10px; padding: 0px 10px 0px 12px; display: inline-flex; }
.chapter-btn[data-tape-hover] { border-color: var(--line-strong); }
.chapter-btn__n { font-family: var(--font-mono); color: var(--accent-text); font-size: 0.74rem; font-weight: 600; }
.chapter-btn__t { white-space: nowrap; text-overflow: ellipsis; font-size: 0.9rem; font-weight: 600; overflow: hidden; }
.chapter-btn svg { color: var(--text-3); flex: 0 0 auto; }
.rail { flex: 1 1 0%; align-items: center; gap: 3px; min-width: 60px; max-width: 520px; margin-left: auto; display: flex; }
.rail__seg { background: var(--line); border-radius: 2px; flex: 1 1 0%; height: 4px; transition: background 0.3s; }
.rail__seg.is-done { background: color-mix(in srgb, var(--accent) 45%, var(--line)); }
.rail__seg.is-current { background: var(--accent); box-shadow: 0 0 10px color-mix(in srgb, var(--accent) 70%, transparent); }
.main { grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(340px, clamp(360px, 34vw, 500px)) minmax(0px, 1fr); gap: 0px; min-height: 0px; display: grid; }
.panel { overscroll-behavior: contain; z-index: 2; border-right: 1px solid var(--line); background: var(--sheet); min-height: 0px; box-shadow: var(--sheet-cast); scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; position: relative; overflow-y: auto; }
.panel__inner { padding: clamp(24px, 4.5vh, 48px) clamp(20px, 2.6vw, 40px) 32px; }
.panel__kicker { color: var(--text-3); align-items: center; gap: 9px; margin: 0px 0px 12px; font-size: 0.84rem; font-weight: 550; display: flex; }
.panel__step { font-family: var(--font-mono); color: var(--accent-text); background: color-mix(in srgb, var(--accent-soft) 80%, transparent); border-radius: 6px; padding: 2px 7px; font-size: 0.74rem; font-weight: 650; }
.panel__title { letter-spacing: -0.022em; text-wrap: balance; margin: 0px 0px 18px; font-size: clamp(1.45rem, 1.1rem + 1vw, 2rem); font-weight: 680; line-height: 1.14; }
.panel__body { color: var(--text-2); font-size: clamp(0.98rem, 0.9rem + 0.2vw, 1.06rem); line-height: 1.65; }
.prose.panel__body > * + * { margin-top: 14px; }
.panel__body > p { margin-bottom: 0px; }
.stage { background: var(--bg-deep); grid-template-rows: auto minmax(0px, 1fr); min-width: 0px; min-height: 0px; display: grid; position: relative; }
.stage__head { justify-content: space-between; align-items: center; gap: 16px; min-height: 64px; padding: 8px clamp(10px, 1.2vw, 18px) 10px clamp(16px, 1.8vw, 30px); display: flex; }
.stage__frame { flex: 1 1 0%; min-width: 0px; }
.stage__frame .frame__head { justify-content: start; gap: 5px; min-height: 0px; display: grid; }
.stage__tools { flex: 0 0 auto; align-items: center; gap: 8px; margin-left: auto; display: flex; }
.viewswitch { border: 1px solid var(--line); background: color-mix(in srgb, var(--bg-deep) 70%, transparent); border-radius: 10px; gap: 2px; padding: 3px; display: inline-flex; box-shadow: rgba(0, 0, 0, 0.3) 0px 1px 2px inset; }
.viewswitch button { cursor: pointer; height: 28px; color: var(--text-3); white-space: nowrap; background: 0px 0px; border: 0px; border-radius: 7px; padding: 0px 12px; font-size: 0.8rem; font-weight: 550; transition: color 0.15s, background 0.15s; }
.viewswitch button[data-tape-hover] { color: var(--text); }
.viewswitch button[aria-pressed="true"] { background: var(--sheen), var(--surface-3); color: var(--text); box-shadow: var(--edge-hi), 0 1px 3px #00000059; }
.stage__zoom { border: 1px solid var(--line); background: var(--sheen), var(--surface); width: 36px; height: 36px; box-shadow: var(--edge-hi), var(--elev-1); }
.stage__zoom[data-tape-hover] { border-color: var(--line-strong); }
.stage__canvas { border: 1px solid var(--line); isolation: isolate; background: radial-gradient(ellipse 65% 60% at 50% 48%, var(--ember-glow), transparent 72%), radial-gradient(ellipse 110% 90% at 50% 0%, color-mix(in srgb, var(--surface) 70%, var(--bg)), var(--bg) 70%); box-shadow: inset 0 1px 0 #ffffff0d, inset 0 0 0 1px #ffffff03, var(--elev-2); border-radius: 16px; margin: 0px clamp(10px, 1.2vw, 18px) clamp(10px, 1.2vw, 18px); overflow: hidden; }
.stage__canvas::before { content: ""; z-index: -1; pointer-events: none; background: radial-gradient(circle at 1px 1px, var(--bg-grid) 1.1px, transparent 0) 0 0 / 22px 22px; position: absolute; inset: 0px; mask-image: radial-gradient(80% 75%, rgb(0, 0, 0) 30%, rgba(0, 0, 0, 0) 100%); }
.stage__canvas { grid-row: 2; grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); min-height: 0px; padding: clamp(10px, 2vh, 24px) clamp(12px, 2vw, 32px) clamp(12px, 2.4vh, 28px); display: grid; position: relative; }
.scene, .fit, .fit__in { grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); min-width: 0px; min-height: 0px; display: grid; }
.zoom-root { z-index: 60; place-items: center; padding: clamp(12px, 3vh, 32px) clamp(12px, 3vw, 40px); display: grid; position: fixed; inset: 0px; }
.zoom-scrim { background: var(--scrim); backdrop-filter: blur(2px); position: absolute; inset: 0px; }
.zoom { background: radial-gradient(ellipse 70% 60% at 50% 50%, var(--ember-glow), transparent 70%), var(--bg); border: 1px solid var(--line); border-radius: var(--radius-l); width: 100%; max-width: 1600px; height: 100%; box-shadow: var(--shadow-2); grid-template-rows: auto minmax(0px, 1fr); display: grid; position: relative; overflow: hidden; }
.zoom__head { border-bottom: 1px solid var(--line); background: var(--surface); justify-content: space-between; align-items: center; gap: 12px; padding: 10px 12px 10px 20px; display: flex; }
.zoom__title { letter-spacing: -0.01em; white-space: nowrap; text-overflow: ellipsis; font-size: 0.98rem; font-weight: 650; overflow: hidden; }
.zoom__ctl { flex: 0 0 auto; align-items: center; gap: 2px; display: inline-flex; }
.zoom__ctl .icon-btn[disabled] { opacity: 0.35; cursor: default; }
.zoom__level { border: 1px solid var(--line); background: var(--surface-2); min-width: 56px; height: 32px; color: var(--text-2); cursor: pointer; border-radius: 8px; padding: 0px 8px; font-size: 0.8rem; font-weight: 600; }
.zoom__level[data-tape-hover] { color: var(--text); border-color: var(--line-strong); }
.zoom__sep { background: var(--line); width: 1px; height: 22px; margin: 0px 6px; }
.zoom__body { background: radial-gradient(circle at 1px 1px, var(--bg-grid) 1px, transparent 0) 0 0 / 22px 22px, var(--bg); min-height: 0px; position: relative; overflow: hidden; }
.zoom__body.is-zoomed { cursor: grab; scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; overflow: auto; }
.zoom__body.is-zoomed[data-tape-active] { cursor: grabbing; }
.zoom__canvas { box-sizing: border-box; width: calc(var(--z,1) * 100%); height: calc(var(--z,1) * 100%); grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); padding: clamp(16px, 3vh, 36px) clamp(16px, 3vw, 48px); display: grid; }
@media (width <= 900px) {
  .zoom-root { padding: 0px; }
  .zoom { border: 0px; border-radius: 0px; }
  .zoom__canvas { padding: 10px; }
  .zoom__body .dg-wrap { overflow: auto; }
}
.evidence { grid-template-rows: minmax(0px, 1fr) auto; gap: 10px; min-height: 0px; margin: 0px; display: grid; }
.evidence__plate { border-radius: var(--radius-m); border: 1px solid var(--line); cursor: zoom-in; background: rgb(255, 255, 255); grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); place-items: center; min-height: 0px; padding: 12px; display: grid; overflow: hidden; }
.evidence__plate img { object-fit: contain; width: 100%; height: 100%; min-height: 0px; display: block; }
.evidence figcaption { color: var(--text-3); text-align: center; font-size: 0.84rem; }
.as-text { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-l); max-width: 62ch; max-height: 100%; color: var(--text-2); place-self: center; padding: 24px 28px; overflow-y: auto; }
.bottombar { z-index: 3; border-top: 1px solid var(--line); background: var(--sheen), var(--sheet); justify-content: space-between; align-items: center; gap: 12px; padding: 0px 16px; display: flex; position: relative; box-shadow: rgba(0, 0, 0, 0.8) 0px -10px 30px -18px; }
.counter { cursor: pointer; min-width: 0px; color: var(--text-2); background: 0px 0px; border: 0px; border-radius: 8px; align-items: center; gap: 12px; padding: 6px 10px; display: inline-flex; }
.counter[data-tape-hover] { background: var(--surface-2); }
.counter__icon { color: var(--text-3); }
.counter__n { font-family: var(--font-mono); color: var(--text); font-variant-numeric: tabular-nums; font-size: 0.88rem; font-weight: 600; }
.counter__of { color: var(--text-3); font-weight: 500; }
.counter__t { white-space: nowrap; text-overflow: ellipsis; max-width: 32ch; font-size: 0.88rem; overflow: hidden; }
.counter__keys { gap: 3px; display: inline-flex; }
.mini-cards { border: 1px solid var(--line); border-radius: var(--radius-m); background: var(--sheen), var(--surface); box-shadow: var(--edge-hi), var(--elev-1); display: grid; overflow: hidden; }
.mini-card { padding: 12px 14px; }
.mini-card + .mini-card { border-top: 1px solid var(--line); }
.mini-card__top { justify-content: space-between; align-items: baseline; gap: 8px; margin-bottom: 4px; display: flex; }
.mini-card__top strong { color: var(--text); font-size: 0.96rem; }
.mini-card__tag { color: var(--text-3); white-space: nowrap; font-size: 0.8rem; }
.mini-card__body { font-size: 0.92rem; line-height: 1.55; }
.callout { border-radius: var(--radius-m); border: 1px solid var(--line); background: var(--surface); box-shadow: var(--edge-hi), var(--elev-1); padding: 12px 14px; font-size: 0.95rem; }
.callout > div:last-child { color: var(--text-2); }
.callout__title { color: var(--text); align-items: center; gap: 7px; margin-bottom: 4px; font-size: 0.9rem; font-weight: 650; display: flex; }
.callout--info { border-color: color-mix(in srgb, var(--cmd) 30%, var(--line)); background: color-mix(in srgb, var(--cmd-soft) 40%, var(--surface)); }
.callout--info .callout__title svg { color: var(--cmd); }
.callout--warn { border-color: color-mix(in srgb, var(--warn) 30%, var(--line)); background: color-mix(in srgb, var(--warn-soft) 40%, var(--surface)); }
.callout--warn .callout__title svg { color: var(--warn); }
.callout--note .callout__title svg { color: var(--accent); }
.predict { border: 1px solid color-mix(in srgb, var(--accent) 40%, var(--line)); border-radius: var(--radius-l); background: var(--sheen), radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--accent-soft) 70%, transparent), transparent 60%), var(--surface); box-shadow: var(--edge-hi), var(--elev-2), 0 0 0 4px color-mix(in srgb, var(--accent) 6%, transparent); padding: 14px; }
.predict__head { color: var(--accent-text); align-items: center; gap: 6px; font-size: 0.8rem; font-weight: 700; display: flex; }
.predict__q { color: var(--text); font-weight: 600; margin: 6px 0px 10px !important; }
.predict__opts { gap: 6px; display: grid; }
.predict__opt { text-align: left; border-radius: var(--radius-m); border: 1px solid var(--line); background: var(--sheen), var(--surface-2); cursor: pointer; width: 100%; color: var(--text); transition: border-color .15s, background .15s, opacity .2s, transform .15s var(--ease-out); box-shadow: var(--edge-hi), 0 1px 2px #00000040; align-items: flex-start; gap: 10px; padding: 9px 12px; font-size: 0.92rem; line-height: 1.45; display: flex; }
.predict__opt[data-tape-hover] { border-color: var(--line-strong); transform: translateY(-1px); }
.predict__mark { border: 1px solid var(--line-strong); width: 22px; height: 22px; font-family: var(--font-mono); color: var(--text-3); border-radius: 999px; flex: 0 0 auto; place-items: center; margin-top: -1px; font-size: 0.7rem; display: grid; }
.predict__opt.is-correct { border-color: var(--evt); background: color-mix(in srgb, var(--evt-soft) 60%, var(--surface)); }
.predict__opt.is-correct .predict__mark { background: var(--evt); border-color: var(--evt); color: var(--surface); }
.predict__opt.is-wrong { border-color: var(--danger); }
.predict__opt.is-wrong .predict__mark { background: var(--danger); border-color: var(--danger); color: var(--surface); }
.predict__opt.is-dim { opacity: 0.6; }
.predict__fb { border-radius: var(--radius-m); background: var(--surface); border: 1px solid var(--line); margin-top: 10px; padding: 10px 12px; font-size: 0.92rem; }
.predict__fb.ok { border-color: color-mix(in srgb, var(--evt) 50%, var(--line)); }
.predict__hint { color: var(--text-3); font-size: 0.82rem; margin-top: 6px !important; }
.decision-chip { text-align: left; cursor: pointer; border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line)); background: var(--sheen), radial-gradient(100% 140% at 0% 50%, color-mix(in srgb, var(--accent-soft) 75%, transparent), transparent 70%), var(--surface); border-radius: var(--radius-m); width: 100%; color: var(--text); box-shadow: var(--edge-hi), var(--elev-1); align-items: center; gap: 12px; padding: 12px 14px; transition: border-color 0.15s, background 0.15s; display: flex; }
.decision-chip[data-tape-hover] { border-color: color-mix(in srgb, var(--accent) 55%, var(--line)); }
.decision-chip[data-tape-hover] .decision-chip__go { color: var(--accent-text); transform: translate(1px, -1px); }
.decision-chip__go { transition: transform .15s var(--ease-out), color .15s; }
.decision-chip__icon { background: var(--accent-soft); width: 32px; height: 32px; color: var(--accent-text); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 35%, transparent), 0 0 16px -4px color-mix(in srgb, var(--accent) 60%, transparent); border-radius: 8px; flex: 0 0 auto; place-items: center; display: grid; }
.decision-chip__body { flex: 1 1 0%; gap: 2px; min-width: 0px; display: grid; }
.decision-chip__label { color: var(--text-3); font-size: 0.8rem; }
.decision-chip__title { font-size: 0.93rem; font-weight: 600; line-height: 1.35; }
.decision-chip__go { color: var(--text-3); flex: 0 0 auto; }
.app--cover .main { background: radial-gradient(ellipse 55% 70% at 22% 40%, var(--ember-glow), transparent 70%), radial-gradient(ellipse 120% 100% at 40% 30%, var(--bg), var(--bg-deep)); grid-template-columns: 1fr; overflow-y: auto; }
.cover { grid-template-columns: minmax(0px, 1.25fr) minmax(280px, 0.75fr); align-items: center; gap: clamp(24px, 5vw, 80px); width: 100%; max-width: 1180px; margin: 0px auto; padding: clamp(24px, 5vh, 64px) clamp(20px, 4vw, 48px); display: grid; }
.cover__phase { color: var(--accent-text); margin: 0px 0px 6px; font-size: 0.8rem; font-weight: 600; }
.cover__num { letter-spacing: -0.06em; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--accent) 22%, var(--surface-3)); text-shadow: 0 1px 0 #ffffff0a, 0 18px 50px color-mix(in srgb, var(--accent) 30%, transparent); margin-bottom: 8px; font-size: clamp(4rem, 3rem + 5vw, 7.5rem); font-weight: 800; line-height: 0.9; font-family: var(--font-sans) !important; }
.cover__title { letter-spacing: -0.034em; text-wrap: balance; margin: 0px 0px 14px; font-size: clamp(2rem, 1.4rem + 2.6vw, 3.4rem); font-weight: 720; line-height: 1.04; }
.cover__sub { color: var(--text-2); max-width: 46ch; margin: 0px 0px 18px; font-size: clamp(1.05rem, 1rem + 0.3vw, 1.25rem); line-height: 1.55; }
.cover__meta { color: var(--text-3); gap: 18px; margin-bottom: 18px; font-size: 0.88rem; display: flex; }
.cover__meta span { align-items: center; gap: 6px; display: inline-flex; }
.cover__intro { color: var(--text-2); max-width: 58ch; margin-bottom: 24px; font-size: 1rem; }
.cover__cta { height: 46px; padding: 0px 22px; font-size: 1rem; }
.cover__side { border-left: 1px solid var(--line); padding: 6px 0px 6px clamp(24px, 3vw, 44px); }
.cover__side-title { color: var(--text-3); margin: 0px 0px 10px; font-size: 0.8rem; font-weight: 600; }
.cover__learn { gap: 8px; margin: 0px 0px 22px; padding: 0px; list-style: none; display: grid; }
.cover__learn li { color: var(--text-2); padding-left: 22px; font-size: 0.94rem; line-height: 1.5; position: relative; }
.cover__learn li::before { content: ""; border-left: 2px solid var(--evt); border-bottom: 2px solid var(--evt); width: 10px; height: 6px; position: absolute; top: 0.5em; left: 2px; transform: rotate(-45deg); }
.cover__route { margin: 0px; padding: 0px; list-style: none; position: relative; }
.cover__route::before { content: ""; background: var(--line); width: 2px; position: absolute; top: 12px; bottom: 12px; left: 6px; }
.cover__route button { text-align: left; cursor: pointer; width: 100%; color: var(--text-2); background: 0px 0px; border: 0px; border-radius: 6px; align-items: center; gap: 12px; padding: 6px 4px 6px 0px; font-size: 0.92rem; display: flex; position: relative; }
.cover__route button[data-tape-hover] { color: var(--text); }
.cover__route-dot { border: 2px solid var(--line-strong); background: var(--bg); border-radius: 999px; flex: 0 0 auto; width: 14px; height: 14px; }
.cover__route button[data-tape-hover] .cover__route-dot { border-color: var(--accent); }
.cover__route-n { color: var(--text-3); margin-left: auto; font-size: 0.7rem; }
.drawer-root { z-index: 50; position: fixed; inset: 0px; }
.drawer-scrim { background: var(--scrim); backdrop-filter: blur(2px); position: absolute; inset: 0px; }
.drawer { background: var(--sheet); border-left: 1px solid var(--line); width: min(600px, 100vw); box-shadow: var(--shadow-2); outline: none; grid-template-rows: auto 1fr; display: grid; position: absolute; top: 0px; bottom: 0px; right: 0px; }
.drawer__head { border-bottom: 1px solid var(--line); background: var(--sheen), radial-gradient(90% 140% at 0% 0%, var(--ember-glow), transparent 70%); justify-content: space-between; align-items: flex-start; gap: 12px; padding: 20px 20px 14px 24px; display: flex; }
.drawer__head h2 { letter-spacing: -0.02em; margin: 4px 0px 0px; font-size: 1.3rem; line-height: 1.25; }
.drawer__label { color: var(--accent-text); align-items: center; gap: 6px; font-size: 0.8rem; font-weight: 600; display: inline-flex; }
.drawer__body { color: var(--text-2); scrollbar-width: thin; padding: 20px 24px 32px; font-size: 0.98rem; line-height: 1.65; overflow-y: auto; }
.drawer__meta { color: var(--text-3); flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 16px; font-size: 0.76rem; display: flex; }
.drawer__gh { margin-top: 20px; }
.seg { border: 1px solid var(--line); border-radius: 9px; padding: 2px; display: inline-flex; }
.seg button { cursor: pointer; color: var(--text-3); background: 0px 0px; border: 0px; border-radius: 6px; padding: 3px 10px; font-size: 0.78rem; }
.seg button[aria-pressed="true"] { background: var(--surface-3); color: var(--text); font-weight: 600; }
.dec { gap: 12px; display: grid; }
.dec__row { border: 1px solid var(--line); border-radius: var(--radius-m); background: var(--sheen), var(--surface); box-shadow: var(--edge-hi), var(--elev-1); padding: 14px 16px; }
.dec__row h3 { margin: 0px 0px 6px; font-size: 0.8rem; }
.dec__row--problem h3 { color: var(--danger); }
.dec__row--decision h3 { color: var(--evt); }
.dec__row--tradeoff h3 { color: var(--warn); }
.dec__adrs { flex-wrap: wrap; gap: 8px; margin-top: 4px; display: flex; }
.steps-list { gap: 2px; margin: 0px 0px 20px; padding: 0px; list-style: none; display: grid; }
.steps-list button { text-align: left; cursor: pointer; width: 100%; color: var(--text-2); background: 0px 0px; border: 0px; border-radius: 8px; align-items: flex-start; gap: 12px; padding: 8px 10px; display: flex; }
.steps-list button[data-tape-hover] { background: var(--surface-2); color: var(--text); }
.steps-list button.is-current { background: color-mix(in srgb, var(--accent-soft) 70%, var(--surface)); color: var(--text); }
.steps-list button.is-current .steps-list__n { color: var(--accent-text); }
.steps-list__n { font-family: var(--font-mono); color: var(--text-3); font-variant-numeric: tabular-nums; padding-top: 3px; font-size: 0.74rem; }
.steps-list__k { color: var(--text-3); font-size: 0.8rem; display: block; }
.steps-list__t { font-size: 0.94rem; font-weight: 550; }
@media (width <= 900px) {
  :root { --topbar-h: 52px; --bottombar-h: 60px; }
  .main { grid-template-rows: minmax(0px, 46%) minmax(0px, 1fr); grid-template-columns: 1fr; }
  .stage { border-bottom: 1px solid var(--line); order: -1; }
  .panel { border-right: 0px; }
  .panel__inner { padding: 18px 16px 24px; }
  .panel__title { margin-bottom: 12px; font-size: 1.35rem; }
  .stage__head { min-height: 46px; padding: 8px 10px 0px; }
  .stage__frame { display: none; }
  .stage__canvas { padding: 8px 10px; }
