.vcase { border-bottom: 1px solid color-mix(in srgb, var(--line) 60%, transparent); grid-template-columns: 220px minmax(0px, 1fr) minmax(0px, 0.72fr); align-items: baseline; gap: 6px 28px; padding: 24px 0px 22px; display: grid; }
