.vw__blurb { color: var(--text-2); text-wrap: pretty; max-width: 62ch; margin: 0px 0px 22px; font-size: 1.06rem; line-height: 1.6; }
html:not([data-lang="en"]) [data-l="en"], html[data-lang="en"] [data-l="es"] { display: none !important; }
.vlang { height: 34px; color: var(--text-2); font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-family: var(--font-mono); letter-spacing: 0.04em; cursor: pointer; background: 0px 0px; border: 0px; border-radius: 999px; align-items: center; gap: 6px; padding: 0px 11px; font-size: 0.76rem; font-weight: 600; transition: color 0.15s, background-color 0.15s; display: inline-flex; }
.vlang[data-tape-hover] { color: var(--text); background: color-mix(in srgb, var(--text) 7%, transparent); }
.vlang[data-tape-focus-visible] { outline: 2px solid var(--accent); outline-offset: 1px; }
.vw__actions { flex-wrap: wrap; gap: 10px; margin-bottom: 34px; display: flex; }
.vw__ideas { background: var(--sheen), var(--sheet); box-shadow: var(--v-ring), var(--edge-hi), var(--elev-1); border-radius: 16px; padding: 22px 24px; }
.vw__ideas h2 { letter-spacing: -0.01em; margin: 0px 0px 12px; font-size: 1.02rem; font-weight: 680; }
.vw__ideas ul { gap: 10px; margin: 0px; padding: 0px; list-style: none; display: grid; }
.vw__ideas li { color: var(--text-2); grid-template-columns: 18px 1fr; align-items: start; gap: 10px; line-height: 1.5; display: grid; }
.vw__ideas li svg { color: var(--evt); margin-top: 3px; }
.vw__pn { grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 28px; display: grid; }
.vw__pn-a { color: var(--text); box-shadow: var(--v-ring); border-radius: 14px; gap: 4px; padding: 14px 16px; text-decoration: none; transition: background-color 0.15s, box-shadow 0.2s; display: grid; }
.vw__pn-a[data-tape-hover] { background: color-mix(in srgb, var(--text) 4.5%, transparent); }
.vw__pn-a--next { text-align: right; }
.vw__pn-k { color: var(--text-3); align-items: center; gap: 6px; font-size: 0.8rem; display: inline-flex; }
.vw__pn-a--next .vw__pn-k { justify-content: flex-end; }
.vw__pn-t { letter-spacing: -0.01em; font-weight: 620; }
.vw__side { background: var(--sheen), var(--sheet); max-height: calc(100dvh - 104px); box-shadow: var(--v-ring), var(--edge-hi), var(--elev-2); border-radius: 16px; grid-template-rows: auto minmax(0px, 1fr) auto; display: grid; position: sticky; top: 82px; overflow: hidden; }
.vtabs { border-bottom: 1px solid var(--line); grid-template-columns: 1fr 1fr; gap: 4px; padding: 6px; display: grid; }
.vtabs button { height: 38px; color: var(--text-3); cursor: pointer; background: 0px 0px; border: 0px; border-radius: 10px; justify-content: center; align-items: center; gap: 8px; font-size: 0.88rem; font-weight: 600; transition: color 0.15s, background-color 0.15s; display: inline-flex; }
.vtabs button[data-tape-hover] { color: var(--text); }
.vtabs button[aria-selected="true"] { color: var(--text); background: color-mix(in srgb, var(--text) 8%, transparent); box-shadow: var(--edge-hi); }
.vw__panel { overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; padding: 8px; overflow-y: auto; }
.vsecs, .vtr { margin: 0px; padding: 0px; list-style: none; }
.vsec { text-align: left; cursor: pointer; background: 0px 0px; border: 0px; border-radius: 11px; grid-template-columns: 46px minmax(0px, 1fr) auto; align-items: center; gap: 10px; width: 100%; padding: 11px 12px; transition: background-color 0.15s; display: grid; position: relative; overflow: hidden; }
.vsec[data-tape-hover] { background: color-mix(in srgb, var(--text) 5%, transparent); }
.vsec__time { color: var(--text-3); font-family: var(--font-mono); font-size: 0.78rem; }
.vsec__t { color: var(--text-2); font-size: 0.93rem; font-weight: 600; }
.vsec__len { color: var(--text-3); font-family: var(--font-mono); font-size: 0.72rem; }
.vsec--past .vsec__t { color: var(--text-3); }
.vsec--now { background: color-mix(in srgb, var(--accent) 10%, transparent); }
.vsec--now .vsec__t { color: var(--text); }
.vsec--now .vsec__time { color: var(--accent-text); }
.vsec__bar { --p: 0; background: color-mix(in srgb, var(--accent) 20%, transparent); border-radius: 2px; height: 2px; position: absolute; bottom: 5px; left: 12px; right: 12px; }
.vsec__bar::after { content: ""; border-radius: inherit; background: var(--accent); transform-origin: 0px center; transform: scaleX(var(--p)); position: absolute; inset: 0px; }
.vtr__l { text-align: left; cursor: pointer; width: 100%; color: var(--text-3); background: 0px 0px; border: 0px; border-radius: 10px; grid-template-columns: 44px minmax(0px, 1fr); gap: 10px; padding: 8px 10px; font-size: 0.92rem; line-height: 1.5; transition: color 0.2s, background-color 0.2s; display: grid; }
.vtr__l[data-tape-hover] { background: color-mix(in srgb, var(--text) 5%, transparent); color: var(--text-2); }
.vtr__time { font-family: var(--font-mono); color: var(--text-3); opacity: 0.8; padding-top: 2px; font-size: 0.74rem; }
.vtr__l.is-past { color: var(--text-2); }
.vtr__l.is-now { color: var(--text); background: color-mix(in srgb, var(--accent) 10%, transparent); }
.vtr__l.is-now .vtr__time { color: var(--accent-text); opacity: 1; }
.vw__keys { border-top: 1px solid var(--line); color: var(--text-3); margin: 0px; padding: 10px 14px; font-size: 0.74rem; }
.vw__keys kbd { background: color-mix(in srgb, var(--text) 8%, transparent); min-width: 18px; font-family: var(--font-mono); text-align: center; color: var(--text-2); border-radius: 5px; padding: 0px 5px; font-size: 0.7rem; display: inline-block; }
:root[data-theme="light"] .v { background: radial-gradient(ellipse 60% 42% at 70% -6%, var(--ember-glow), transparent 70%), var(--bg); }
:root[data-theme="light"] .vh-feature__frame { box-shadow: rgba(20, 20, 20, 0.1) 0px 0px 0px 1px, rgba(40, 30, 20, 0.45) 0px 30px 70px -32px; }
:root[data-theme="light"] .vp { box-shadow: rgba(20, 20, 20, 0.1) 0px 0px 0px 1px, rgba(40, 30, 20, 0.5) 0px 30px 70px -32px; }
@media (width <= 1180px) {
  .vw { grid-template-columns: minmax(0px, 1fr) 330px; gap: 22px; }
}
@media (width <= 980px) {
  .vh-hero { grid-template-columns: 1fr; padding-top: 28px; }
  .vh-feature__frame { transform: none; }
  .vh-phase { grid-template-columns: 1fr; gap: 10px; padding: 24px 0px 18px; }
  .vh-phase__t { margin: 0px; position: static; }
  .vw { grid-template-columns: 1fr; padding-top: 0px; }
  .vw__main { margin: 0 calc(-1 * var(--v-gut)); }
  .vp { border-radius: 0px; }
  .vw__info { padding: 22px var(--v-gut) 0; }
  .vw__side { max-height: 70vh; margin-top: 4px; position: static; }
}
@media (width <= 640px) {
  .vtop__crumb { border-left: 0px; padding-left: 4px; }
  .vtop__crumb span { display: none; }
  .vch { grid-template-columns: 132px minmax(0px, 1fr); align-items: start; gap: 14px; }
  .vch__state { grid-column: 2; padding: 0px; }
  .vch__d { display: none; }
  .vch__t { font-size: 1rem; }
  .hide-xs { display: none !important; }
  .vp { aspect-ratio: auto; overflow: visible; }
  .vp__video { aspect-ratio: 16 / 9; height: auto; }
  .vp__screen { height: auto; }
  .vp:not(.is-idle) .vcc { transform: none; }
  .vcc { bottom: 4%; left: 2%; right: 2%; }
  .vcc__box { max-width: 96%; font-size: calc(var(--cc-k) * clamp(12px, 3.4cqw, 20px)); }
  .vp:has(.vp__menu) { z-index: 30; }
  .vp__menu { background: rgb(14, 16, 21); width: auto; position: fixed; bottom: 12px; left: 12px; right: 12px; }
  .vp__ctrl { background: rgb(0, 0, 0); padding: 2px 6px 6px; position: static; }
  .vp.is-idle .vp__ctrl { opacity: 1; pointer-events: auto; transform: none; }
  .vp.is-idle { cursor: auto; }
  .vp__big { top: 28.125vw; }
  .vp__end { aspect-ratio: 16 / 9; bottom: auto; }
  .vp__btn { min-width: 32px; height: 32px; padding: 0px 6px; }
  .vp__btn svg { width: 16px; height: 16px; }
  .vp__time { margin: 0px 4px; font-size: 0.74rem; }
  .vp__track { height: 18px; }
  .vh-hero__facts { font-size: 0.86rem; }
  .vp__big { width: 64px; height: 64px; margin: -32px 0px 0px -32px; }
  .vw__pn { grid-template-columns: 1fr; }
  .vw__pn-a--next { text-align: left; }
  .vw__pn-a--next .vw__pn-k { justify-content: flex-start; }
  .vh-syl__head { flex-direction: column; gap: 6px; }
}
@media (prefers-reduced-motion: reduce) {
  .vh-feature__frame, .vh-feature__play, .vbtn, .vch__thumb img { transition: none; }
  .vh-feature__frame { transform: none; }
  .vp__spin { animation-duration: 2s; }
}
